package com.own.order.repository;
import com.own.order.domain.AfterSale; import com.own.order.domain.AfterSaleStatus; import java.util.List; import javax.persistence.LockModeType; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Lock; import org.springframework.data.jpa.repository.Query;
public interface AfterSaleRepository extends JpaRepository<AfterSale,Long>{ AfterSale findByAfterSaleNo(String afterSaleNo); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select s from AfterSale s where s.afterSaleNo = ?1") AfterSale findByAfterSaleNoForUpdate(String afterSaleNo); List<AfterSale> findByBuyerIdOrderByIdDesc(Long buyerId); List<AfterSale> findByMerchantIdOrderByIdDesc(Long merchantId); @Query("select s from AfterSale s where s.buyerId = ?1 and (?2 is null or s.status = ?2) order by s.id desc") Page<AfterSale> pageByBuyer(Long buyerId, AfterSaleStatus status, Pageable pageable); @Query("select s from AfterSale s where s.merchantId = ?1 and (?2 is null or s.status = ?2) order by s.id desc") Page<AfterSale> pageByMerchant(Long merchantId, AfterSaleStatus status, Pageable pageable); List<AfterSale> findBySubOrderNoAndStatusIn(String subOrderNo, List<AfterSaleStatus> statuses); List<AfterSale> findBySubOrderNoOrderByIdAsc(String subOrderNo); List<AfterSale> findByStatus(AfterSaleStatus status); List<AfterSale> findByStatusAndCreatedAtBefore(AfterSaleStatus status, java.util.Date createdAt); }
